R["SphU.java"] = [
 ("/**\n * <p>The fundamental Sentinel API for recording statistics and performing rule checking for resources.</p>\n * <p>\n * Conceptually, physical or logical resource that need protection should be\n * surrounded by an entry. The requests to this resource will be blocked if any\n * criteria is met, eg. when any {@link Rule}'s threshold is exceeded. Once blocked,\n * a {@link BlockException} will be thrown.\n * </p>\n * <p>\n * To configure the criteria, we can use <code>XxxRuleManager.loadRules()</code> to load rules.\n * </p>\n *\n * <p>\n * Following code is an example, {@code \"abc\"} represent a unique name for the\n * protected resource:\n * </p>\n *\n * <pre>\n *  public void foo() {\n *     Entry entry = null;\n *     try {\n *        entry = SphU.entry(\"abc\");\n *        // resource that need protection\n *     } catch (BlockException blockException) {\n *         // when goes there, it is blocked\n *         // add blocked handle logic here\n *     } catch (Throwable bizException) {\n *         // business exception\n *         Tracer.trace(bizException);\n *     } finally {\n *         // ensure finally be executed\n *         if (entry != null){\n *             entry.exit();\n *         }\n *     }\n *  }\n * </pre>\n *\n * <p>\n * Make sure {@code SphU.entry()} and {@link Entry#exit()} be paired in the same thread,\n * otherwise {@link ErrorEntryFreeException} will be thrown.\n * </p>\n *\n * @author jialiang.linjl\n * @author Eric Zhao\n * @see SphO\n */", "/**\n * <p>Sentinel 记录资源统计并执行规则检查的基础 API。</p>\n * <p>\n * 概念上，需要保护的物理或逻辑资源应被 Entry 包裹。若满足任一条件\n *（例如任一 {@link Rule} 阈值被超过），对该资源的请求将被阻断，并抛出\n * {@link BlockException}。\n * </p>\n * <p>\n * 可通过 <code>XxxRuleManager.loadRules()</code> 加载规则以配置条件。\n * </p>\n *\n * <p>\n * 示例如下，{@code \"abc\"} 表示受保护资源的唯一名称：\n * </p>\n *\n * <pre>\n *  public void foo() {\n *     Entry entry = null;\n *     try {\n *        entry = SphU.entry(\"abc\");\n *        // 需要保护的资源\n *     } catch (BlockException blockException) {\n *         // 进入此处表示被阻断\n *         // 在此添加阻断处理逻辑\n *     } catch (Throwable bizException) {\n *         // 业务异常\n *         Tracer.trace(bizException);\n *     } finally {\n *         // 确保 finally 被执行\n *         if (entry != null){\n *             entry.exit();\n *         }\n *     }\n *  }\n * </pre>\n *\n * <p>\n * 确保 {@code SphU.entry()} 与 {@link Entry#exit()} 在同一线程中配对调用，\n * 否则将抛出 {@link ErrorEntryFreeException}。\n * </p>\n *\n * @author jialiang.linjl\n * @author Eric Zhao\n * @see SphO\n */"),
 ("     * Record statistics and check all rules of the resource that indicates an async invocation.", "     * 对表示异步调用的资源记录统计并检查全部规则。"),
 ("     * Record statistics and perform rule checking for the given resource. The entry is prioritized.", "     * 对给定资源记录统计并执行规则检查，Entry 具有优先级。"),
]
R["Tracer.java"] = [
 ("/**\n * This class is used to record other exceptions except block exception.\n *\n * @author jialiang.linjl\n * @author Eric Zhao\n */", "/**\n * 用于记录除 BlockException 以外的其他异常。\n *\n * @author jialiang.linjl\n * @author Eric Zhao\n */"),
 ("    /**\n     * Trace provided {@link Throwable} to the resource entry in current context.\n     *\n     * @param e exception to record\n     */", "    /**\n     * 将给定 {@link Throwable} 追踪到当前上下文中的资源 Entry。\n     *\n     * @param e 要记录的异常\n     */"),
 ("    /**\n     * Trace provided {@link Throwable} to current entry in current context.\n     *\n     * @param e     exception to record\n     * @param count exception count to add\n     */", "    /**\n     * 将给定 {@link Throwable} 追踪到当前上下文中的当前 Entry。\n     *\n     * @param e     要记录的异常\n     * @param count 要增加的异常计数\n     */"),
 ("    /**\n     * Trace provided {@link Throwable} to current entry of given entrance context.\n     *\n     * @param e     exception to record\n     * @param context target entrance context\n     * @since 1.8.0\n     */", "    /**\n     * 将给定 {@link Throwable} 追踪到指定入口上下文的当前 Entry。\n     *\n     * @param e       要记录的异常\n     * @param context 目标入口上下文\n     * @since 1.8.0\n     */"),
 ("    /**\n     * Trace provided {@link Throwable} and add exception count to current entry in provided context.\n     *\n     * @param e     exception to record\n     * @param count exception count to add\n     * @since 1.4.2\n     */", "    /**\n     * 将给定 {@link Throwable} 追踪到指定上下文中当前 Entry 并增加异常计数。\n     *\n     * @param e     要记录的异常\n     * @param count 要增加的异常计数\n     * @since 1.4.2\n     */"),
 ("    /**\n     * Trace provided {@link Throwable} to the given resource entry.\n     *\n     * @param e exception to record\n     * @since 1.4.2\n     */", "    /**\n     * 将给定 {@link Throwable} 追踪到指定资源 Entry。\n     *\n     * @param e 要记录的异常\n     * @since 1.4.2\n     */"),
 ("    /**\n     * Set exception to trace. If not set, all Exception except for {@link BlockException} will be traced.\n     * <p>\n     * Note that if both {@link #setExceptionsToIgnore(Class[])} and this method is set,\n     * the ExceptionsToIgnore will be of higher precedence.\n     * </p>\n     *\n     * @param traceClasses the list of exception classes to trace.\n     * @since 1.6.1\n     */", "    /**\n     * 设置要追踪的异常。若未设置，除 {@link BlockException} 外的所有 Exception 都会被追踪。\n     * <p>\n     * 注意若同时设置 {@link #setExceptionsToIgnore(Class[])} 与本方法，\n     * ExceptionsToIgnore 优先级更高。\n     * </p>\n     *\n     * @param traceClasses 要追踪的异常类列表\n     * @since 1.6.1\n     */"),
 ("    /**\n     * Get exception classes to trace.\n     *\n     * @return an array of exception classes to trace.\n     * @since 1.6.1\n     */", "    /**\n     * 获取要追踪的异常类。\n     *\n     * @return 要追踪的异常类数组\n     * @since 1.6.1\n     */"),
 ("    /**\n     * Set exceptions to ignore. if not set, all Exception except for {@link BlockException} will be traced.\n     * <p>\n     * Note that if both {@link #setExceptionsToTrace(Class[])} and this method is set,\n     * the ExceptionsToIgnore will be of higher precedence.\n     * </p>\n     *\n     * @param ignoreClasses the list of exception classes to ignore.\n     * @since 1.6.1\n     */", "    /**\n     * 设置要忽略的异常。若未设置，除 {@link BlockException} 外的所有 Exception 都会被追踪。\n     * <p>\n     * 注意若同时设置 {@link #setExceptionsToTrace(Class[])} 与本方法，\n     * ExceptionsToIgnore 优先级更高。\n     * </p>\n     *\n     * @param ignoreClasses 要忽略的异常类列表\n     * @since 1.6.1\n     */"),
 ("    /**\n     * Get exception classes to ignore.\n     *\n     * @return an array of exception classes to ignore.\n     * @since 1.6.1\n     */", "    /**\n     * 获取要忽略的异常类。\n     *\n     * @return 要忽略的异常类数组\n     * @since 1.6.1\n     */"),
 ("    /**\n     * Get exception predicate\n     * @return the exception predicate.\n     */", "    /**\n     * 获取异常谓词。\n     * @return 异常谓词\n     */"),
 ("    /**\n     * set an exception predicate which indicates the exception should be traced(return true) or ignored(return false)\n     * except for {@link BlockException}\n     * @param exceptionPredicate the exception predicate\n     */", "    /**\n     * 设置异常谓词，指示异常应被追踪（返回 true）还是忽略（返回 false），\n     * {@link BlockException} 除外。\n     * @param exceptionPredicate 异常谓词\n     */"),
 ("    /**\n     * Check whether the throwable should be traced.\n     *\n     * @param t the throwable to check.\n     * @return true if the throwable should be traced, else return false.\n     */", "    /**\n     * 检查 Throwable 是否应被追踪。\n     *\n     * @param t 要检查的 Throwable\n     * @return 若应追踪则返回 true，否则返回 false\n     */"),
]
R["SentinelResource.java"] = [
 ("/**\n * The annotation indicates a definition of Sentinel resource.\n *\n * @author Eric Zhao\n * @author zhaoyuguang\n * @since 0.1.1\n */", "/**\n * 表示 Sentinel 资源定义的注解。\n *\n * @author Eric Zhao\n * @author zhaoyuguang\n * @since 0.1.1\n */"),
 ("    /**\n     * @return name of the Sentinel resource\n     */", "    /**\n     * @return Sentinel 资源名称\n     */"),
 ("    /**\n     * @return the entry type (inbound or outbound), outbound by default\n     */", "    /**\n     * @return Entry 类型（入站或出站），默认为出站\n     */"),
 ("    /**\n     * @return the classification (type) of the resource\n     * @since 1.7.0\n     */", "    /**\n     * @return 资源分类（类型）\n     * @since 1.7.0\n     */"),
 ("    /**\n     * @return name of the block exception function, empty by default\n     */", "    /**\n     * @return 阻断异常处理函数名称，默认为空\n     */"),
 ("    /**\n     * The {@code blockHandler} is located in the same class with the original method by default.\n     * However, if some methods share the same signature and intend to set the same block handler,\n     * then users can set the class where the block handler exists. Note that the block handler method\n     * must be static.\n     *\n     * @return the class where the block handler exists, should not provide more than one classes\n     */", "    /**\n     * {@code blockHandler} 默认与原方法位于同一类。\n     * 若多个方法签名相同且共用同一 blockHandler，\n     * 可指定 blockHandler 所在类。注意 blockHandler 方法必须为 static。\n     *\n     * @return blockHandler 所在类，不应提供多个类\n     */"),
 ("    /**\n     * @return name of the fallback function, empty by default\n     */", "    /**\n     * @return 降级函数名称，默认为空\n     */"),
 ("    /**\n     * The {@code defaultFallback} is used as the default universal fallback method.\n     * It should not accept any parameters, and the return type should be compatible\n     * with the original method.\n     *\n     * @return name of the default fallback method, empty by default\n     * @since 1.6.0\n     */", "    /**\n     * {@code defaultFallback} 用作默认通用降级方法。\n     * 不应接受任何参数，返回类型应与原方法兼容。\n     *\n     * @return 默认降级方法名称，默认为空\n     * @since 1.6.0\n     */"),
 ("    /**\n     * The {@code fallback} is located in the same class with the original method by default.\n     * However, if some methods share the same signature and intend to set the same fallback,\n     * then users can set the class where the fallback function exists. Note that the shared fallback method\n     * must be static.\n     *\n     * @return the class where the fallback method is located (only single class)\n     * @since 1.6.0\n     */", "    /**\n     * {@code fallback} 默认与原方法位于同一类。\n     * 若多个方法签名相同且共用同一 fallback，\n     * 可指定 fallback 所在类。注意共用 fallback 方法必须为 static。\n     *\n     * @return fallback 方法所在类（仅单个类）\n     * @since 1.6.0\n     */"),
 ("    /**\n     * @return the list of exception classes to trace, {@link Throwable} by default\n     * @since 1.5.1\n     */", "    /**\n     * @return 要追踪的异常类列表，默认为 {@link Throwable}\n     * @since 1.5.1\n     */"),
 ("    /**\n     * Indicates the exceptions to be ignored. Note that {@code exceptionsToTrace} should\n     * not appear with {@code exceptionsToIgnore} at the same time, or {@code exceptionsToIgnore}\n     * will be of higher precedence.\n     *\n     * @return the list of exception classes to ignore, empty by default\n     * @since 1.6.0\n     */", "    /**\n     * 指定要忽略的异常。注意 {@code exceptionsToTrace} 不应与\n     * {@code exceptionsToIgnore} 同时出现，否则 {@code exceptionsToIgnore} 优先级更高。\n     *\n     * @return 要忽略的异常类列表，默认为空\n     * @since 1.6.0\n     */"),
]
for fn in ("Sph.java","SphU.java","SphO.java","SphResourceTypeSupport.java"):
    R[fn] = R.get(fn,[]) + COMMON

def apply(text, reps):
    for o,n in reps:
        if o in text: text = text.replace(o,n)
    return text

failures=[]; ok=0
for rel in BATCH_FILES:
    dst = ANALYZED / rel
    name = Path(rel).name
    text = dst.read_text(encoding="utf-8")
    if len(re.findall(r"[\u4e00-\u9fff]", text)) >= 10:
        ok+=1; print(f"SKIP {rel}"); continue
    text = apply(text, R.get(name,[]))
    cn = len(re.findall(r"[\u4e00-\u9fff]", text))
    if cn < 10 or "Licensed under the Apache License" not in text:
        failures.append(f"VALIDATION cn={cn}: {rel}"); continue
    dst.write_text(text, encoding="utf-8"); ok+=1; print(f"OK cn={cn} {rel}")
print(json.dumps({"ok":ok,"failures":failures}))
